<script lang="ts">
 import {tick} from 'svelte';
 import MoveCard from './MoveCard.svelte';
 import Fighter from './Fighter.svelte';
 import BattleArena from './BattleArena.svelte';
 import {characters,trials,createSession,input,resolve,roleCards,type Session,type Input,type Mode} from './engine';
 import {AXES} from './cards';
 import {DEFAULT_CONFIG,type MergeConfig} from './config';
 let {config=DEFAULT_CONFIG}:{config?:MergeConfig}=$props();
 let session=$state<Session|null>(null);
 let stage=$state(0);
 let heading=$state<HTMLHeadingElement>();
 let actor=$derived(session?.phase==='character2'||session?.phase==='move2'?1:0);
 let result=$derived(session&&['battle','result'].includes(session.phase)?resolve(session.ids as number[],session.moves as string[],session.trial,session.config):null);
 async function focus(){await tick();heading?.focus();}
 function start(mode:Mode){const judge=config.judges[Math.floor(Math.random()*config.judges.length)];session=createSession(mode,judge,config);void focus();}
 function send(event:Input){if(session){session=input(session,event);void focus();}}
 $effect(()=>{
  if(session?.phase!=='battle')return;
  stage=0;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const timers=[1,2,3,4,5,6].map((value)=>window.setTimeout(()=>{stage=value},reduced?value*150:[0,800,1600,2400,3400,5200,7600][value]));
  return()=>timers.forEach(clearTimeout);
 });
</script>
<svelte:head><title>Merge Battle · BacaroTech Game Center</title><meta name="description" content="Due branch, tre carte. Scegli, lancia e scopri il merge."/></svelte:head>
<main class="mb-shell"><svg class="mb-gitgraph" viewBox="0 0 900 1200" preserveAspectRatio="none" aria-hidden="true"><path d="M60 0V180Q60 240 140 240T220 320V700Q220 780 140 780T60 860V1200"/><path d="M840 0V340Q840 400 760 400T680 480V700Q680 780 760 780T840 860V1200"/><path d="M450 0V650Q450 740 220 780M450 650Q450 740 680 780M450 650V1200"/>{#each [160,420,620,950,1100] as y}<circle cx="60" cy={y} r="8"/><circle cx="840" cy={y+30} r="8"/>{/each}</svg>
 <div class="mb-mast"><span>Merge Battle</span>{#if session}<span>{session.mode === 'solo' ? 'Un giocatore' : 'Due giocatori'}</span>{/if}</div>
 {#if !session}
  <div class="mb-intro"><h1 bind:this={heading} tabindex="-1">MERGE<br/><em>BATTLE!</em></h1><p>Dev e data science sullo stesso campo.<br/>Due scelte segrete. Un solo merge.</p>
  <div class="mb-poster" aria-hidden="true"><Fighter id={config.characters[0]}/><b>VS</b><Fighter id={config.characters[1]}/></div></div>
  <div class="mb-mode"><button onclick={()=>start('local')}><strong>Gioca in due</strong><span>Sullo stesso telefono o computer</span></button><button class="mb-alt" onclick={()=>start('solo')}><strong>Gioca da solo</strong><span>Contro il computer</span></button></div>
  <details class="mb-how"><summary>Come si gioca</summary><ol><li><b>Scegli il tuo ruolo.</b> Ogni personaggio ha tre carte mossa.</li><li><b>Leggi i criteri del maintainer.</b> Il maintainer valuta le proposte e decide cosa integrare. Rapidità, Solidità, Evidenza e Adattabilità contano in modo diverso in ogni scenario.</li><li><b>Giocate una carta a testa, in segreto.</b> Sullo stesso telefono scegliete a turno, senza guardare la scelta dell’altro.</li><li><b>Scoprite l’esito e il merge.</b> Ogni valore viene moltiplicato per il peso assegnato dal maintainer: vince la somma più alta. Stessa somma? Pareggio. I due ruoli si fondono comunque.</li></ol><p class="mb-example">Per esempio: Rapidità <b>4</b> con peso <b>×3</b> vale <b>12 punti</b>. Si aggiungono i punti degli altri tre attributi.</p><details><summary>Cosa significano i quattro attributi?</summary><p><b>Rapidità:</b> ottenere un risultato subito. <b>Solidità:</b> resistere a errori e problemi. <b>Evidenza:</b> verifiche e dati a supporto. <b>Adattabilità:</b> gestire cambiamenti e riuso.</p></details></details>
  <p class="mb-note">Scegli senza fretta. Niente quiz, niente cronometri. </p>
 {:else if session.phase==='character1'||session.phase==='character2'}
  <p class="mb-eyebrow">CHECKOUT / SCEGLI IL RUOLO</p><h1 bind:this={heading} tabindex="-1">{actor===0?'Player 1':'Player 2'}, scegli il tuo branch.</h1><p>{session.mode==='solo'?'Scegli il tuo ruolo: il computer ne prenderà un altro.':'Scegliete un ruolo alla volta. Le competenze si uniscono dopo lo scontro.'}</p>
  <div class="mb-cast">{#each characters.filter(c=>session!.allowedCharacters.includes(c.id)) as c}<button class="mb-character" disabled={session.ids.includes(c.id)} onclick={()=>send({type:'character',actor:actor as 0|1,value:c.id})} style:--accent={c.color}><Fighter id={c.id}/><strong>{c.name}</strong><span>{c.trait}</span>{#if session.ids.includes(c.id)}<small>Scelto da Player 1</small>{/if}</button>{/each}</div>
 {:else if session.phase==='brief'}
  <p class="mb-eyebrow">ROUND {session.round+1} / {trials[session.trial].place}</p><h1 bind:this={heading} tabindex="-1">{trials[session.trial].title}</h1><div class="mb-brief"><span class="mb-jury-icon" aria-hidden="true">{trials[session.trial].icon}</span><p>Il maintainer: <strong>{trials[session.trial].jury}</strong></p><p>Il maintainer valuta le proposte e decide cosa integrare usando questi criteri di review.</p></div>
  <div class="mb-weights"><strong>Criteri di review</strong>{#each AXES as axis,i}<span>{axis} ×{session.config.weights[session.trial][i]}</span>{/each}<small>Valore della carta × peso, poi somma. Punteggi uguali: pareggio.</small></div><div class="mb-versus">{#each session.ids as id,i}<div><Fighter id={id!}/><b>{i===1&&session.mode==='solo'?'Rivale del gioco':`Player ${i+1}`}</b><p>{characters[id!].name}</p></div>{/each}</div>
  <p class="mb-note">{session.mode==='local'?'Player 2, guarda altrove. Player 1 sta per scegliere una mossa segreta.':'Il rivale fissa la propria carta prima della tua scelta.'}</p><button class="mb-primary" onclick={()=>send({type:'ready'})}>Scegliamo le mosse →</button>
 {:else if session.phase==='move1'||session.phase==='move2'}
  <p class="mb-eyebrow">SCELTA SEGRETA / PLAYER {actor+1}</p><h1 bind:this={heading} tabindex="-1">Come te la giochi?</h1><p>{trials[session.trial].title}</p><p><strong>{characters[session.ids[actor]!].name}</strong> · La scelta si conferma al tocco.</p>
  <div class="mb-weights">{#each AXES as axis,i}<span>{axis} ×{session.config.weights[session.trial][i]}</span>{/each}</div>
  <div class="mb-hand">{#each roleCards(session.config,session.ids[actor]!) as card}<MoveCard {card} accent={characters[session.ids[actor]!].color} role={characters[session.ids[actor]!].short} onplay={()=>send({type:'move',actor:actor as 0|1,value:card.id})} />{/each}</div><p class="mb-note">Tocca «Gioca carta» per confermare la tua scelta segreta.</p>
 {:else if session.phase==='handoff'}
  <div class="mb-handoff"><span aria-hidden="true">↔</span><h1 bind:this={heading} tabindex="-1">Passa il telefono al tuo avversario.</h1><p>La prima scelta è nascosta.<br/>Player 1, adesso guarda altrove.</p><button class="mb-primary" onclick={()=>send({type:'handoff'})}>Sono Player 2. Tocca a me →</button></div>
 {:else if session.phase==='battle'&&result}
  <p class="mb-eyebrow">{trials[session.trial].place}</p><h1 bind:this={heading} tabindex="-1">{stage<4?'Tenetevi pronti.':'Merge in corso.'}</h1>
  <BattleArena ids={session.ids as number[]} moves={session.moves as string[]} config={session.config} trial={session.trial} {stage}/>
  {#if stage>=4}<div class="mb-reveal">{#each session.ids as id,i}<p><b>{i===1&&session.mode==='solo'?'Rivale':`Player ${i+1}`} / {characters[id!].short}</b><br/>{session.config.cards.find(c=>c.id===session!.moves[i])?.name}</p>{/each}</div>{/if}
  <div aria-live="polite">{#if stage>=5}<p class="mb-gag">{result.gag}</p>{/if}{#if stage>=6}<blockquote><b>{trials[session.trial].jury}</b><br/>«{result.reason}»</blockquote>{#if session.mode==='solo'}<p class="mb-note">{session.botLine}</p>{/if}<button class="mb-primary" onclick={()=>send({type:'finish'})}>Scopri esito e merge →</button>{/if}</div>
 {:else if session.phase==='result'&&result}
  <p class="mb-eyebrow">ESITO DELLA REVIEW</p><h1 bind:this={heading} tabindex="-1">{result.winner===null?'Pareggio!':session.mode==='solo'?(result.winner===0?'Vince il tuo branch!':'Vince il rivale!'):`Vince Player ${result.winner+1}!`}</h1>
  {#if result.winner!==null}<p><strong>{characters[session.ids[result.winner]!].name}</strong></p>{/if}
  <div class="mb-scoreboard">{#each result.calculations as calculation,i}<p><b>Player {i+1} · {result.scores[i]} punti</b><br/>{calculation}</p>{/each}</div>
  <blockquote>{result.reason}<br/><small>— {trials[session.trial].jury}</small></blockquote>
  <div class="mb-merge"><span class="mb-eyebrow">MERGE ATTACK / COMPETENZE COMBINATE</span><Fighter id={session.ids[0]!} other={session.ids[1]!} emotion="win"/><h2>{result.hybrid}</h2><p>{result.hybridGag}</p></div>
  <button class="mb-primary" onclick={()=>send({type:'rematch'})}>Rivincita! Cambiamo maintainer →</button><button class="mb-text" onclick={()=>start(session!.mode)}>Cambiamo personaggi</button>
 {/if}
 {#if session}<button class="mb-exit" onclick={()=>{session=null;void focus()}}>← Scegli modalità</button>{/if}
</main>
<style>
 .mb-hand{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:28px 0 32px;align-items:stretch}.mb-how{margin:28px 0;padding:22px;background:var(--arcade-panel);border:1px solid var(--arcade-border);border-radius:14px;text-align:left}.mb-how>summary{font-size:20px;font-weight:700}.mb-how ol{padding-left:24px;line-height:1.65;font-size:14px}.mb-how li{padding:4px 0 4px 5px}.mb-example{padding:12px;background:var(--arcade-raised);border-radius:6px;font-size:13px;line-height:1.6}.mb-how details{font-size:13px;line-height:1.6}.mb-how summary{cursor:pointer;min-height:36px;display:list-item;align-content:center}@media(max-width:700px){.mb-hand{gap:14px;grid-template-columns:1fr;max-width:360px;margin:24px auto 32px}.mb-how{padding:18px}.mb-how ol{font-size:13px}}

 .mb-weights{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0;padding:16px;background:var(--arcade-panel);border:1px solid var(--arcade-border);border-radius:10px;font-size:13px}.mb-weights strong,.mb-weights>small{flex-basis:100%}.mb-weights>span{padding:6px;background:var(--arcade-raised);border-radius:4px}.mb-scoreboard{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mb-scoreboard p{padding:16px;background:var(--arcade-panel);line-height:1.6;overflow-wrap:anywhere}@media(max-width:520px){.mb-scoreboard{grid-template-columns:1fr}}

 .mb-shell{position:relative;isolation:isolate;background:var(--arcade-bg)}.mb-gitgraph{position:absolute;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none;opacity:.18;fill:none;stroke:#287c76;stroke-width:3}.mb-gitgraph path:nth-child(2){stroke:#7956af}.mb-gitgraph path:nth-child(3){stroke:#b68a28}.mb-cast{grid-template-columns:repeat(3,1fr)}@media(max-width:650px){.mb-cast{grid-template-columns:1fr 1fr}}

 .mb-shell{max-width:900px;margin:auto;padding:24px 24px 50px;color:var(--arcade-text);font-family:'Trebuchet MS',sans-serif}.mb-mast{display:flex;justify-content:space-between;gap:12px;font-size:15px;font-weight:700;letter-spacing:0;border-bottom:1px solid var(--arcade-border);padding:0 0 16px;margin-bottom:30px}.mb-shell h1{font-size:clamp(28px,4.8vw,44px);line-height:1.07;letter-spacing:-1.6px;max-width:760px;margin:12px 0 20px}.mb-shell h1:focus{outline:none}.mb-eyebrow{font-size:11px;font-weight:900;letter-spacing:1.6px}.mb-intro{text-align:center}.mb-intro h1{font-size:clamp(62px,12vw,100px);margin:16px auto;line-height:.86;letter-spacing:-5px;font-weight:950}.mb-intro em{color:var(--arcade-violet);font-style:normal}.mb-intro>p{line-height:1.6}.mb-poster{display:flex;justify-content:center;align-items:center;gap:30px;margin:25px 0}.mb-poster>b{font-style:italic;font-size:34px;rotate:-12deg;background:#f6cb5e;color:#282038;border:2px solid;padding:12px;border-radius:50%}.mb-mode{display:grid;grid-template-columns:1fr 1fr;gap:14px}.mb-mode button{display:grid;text-align:left;gap:14px;padding:24px;background:var(--arcade-violet);color:#15151b;border:2px solid #282038;border-radius:16px;box-shadow:4px 4px 0 #282038}.mb-mode strong{font-size:27px}.mb-mode span{font-size:13px;line-height:1.5}.mb-mode .mb-alt{background:#f6cb5e;color:#282038;color:#282038}.mb-note{font-size:14px;line-height:1.6;color:var(--arcade-muted);margin:22px 0}.mb-cast{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:26px}.mb-character{background:var(--accent);color:#282038;border:2px solid;border-radius:18px;padding:22px 12px;display:grid;justify-items:center;gap:12px;text-align:center}.mb-character:hover:not(:disabled){background:var(--accent);filter:brightness(1.05)}.mb-character:disabled{opacity:.45}.mb-character strong{font-size:13px}.mb-character span{font-size:13px;max-width:24ch;line-height:1.5}.mb-primary{box-shadow:0 4px 0 #0c0c10;background:var(--arcade-violet);color:#15151b;border:2px solid #282038;border-radius:12px;padding:16px 24px;min-height:54px;width:100%;font-weight:800}.mb-primary:hover{background:#c9b5ff}.mb-brief{border:2px solid #282038;background:#f6cb5e;color:#282038;border-radius:16px;padding:20px;text-align:center}.mb-jury-icon{font-size:55px}.mb-versus{display:flex;justify-content:space-evenly;gap:12px;margin-top:25px;text-align:center}.mb-versus>div{display:grid;justify-items:center;font-size:12px}.mb-versus b{margin-top:10px}.mb-handoff{text-align:center;min-height:430px;display:grid;align-content:center;justify-items:center;gap:15px}.mb-handoff>span{font-size:80px}.mb-handoff p{line-height:1.8}.mb-reveal{display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:13px;line-height:1.5}.mb-reveal p{padding:15px;background:var(--arcade-panel);border-radius:12px;margin:0}.mb-gag{font-weight:800;line-height:1.6}.mb-shell blockquote{margin:22px 0;padding:20px;border-left:5px solid #7944b2;background:var(--arcade-panel);border-radius:0 14px 14px 0;line-height:1.6}.mb-merge{display:grid;justify-items:center;text-align:center;gap:14px;padding:28px 15px;background:#f6cb5e;color:#282038;border:2px solid #282038;border-radius:20px;margin:24px 0}.mb-merge h2{font-size:clamp(22px,4vw,32px);margin:0;overflow-wrap:anywhere}.mb-merge p{margin:0;line-height:1.6}.mb-text,.mb-exit{background:transparent;color:var(--arcade-muted);border:0;text-decoration:underline;font-size:13px;padding:14px}.mb-text{display:block;margin:8px auto}.mb-exit{margin-top:25px}.mb-shell button:focus-visible{outline:3px solid #ff9a64;outline-offset:4px}
 @media(max-width:520px){.mb-shell{padding:20px 16px 35px}.mb-mast{font-size:14px;letter-spacing:0}.mb-mode{grid-template-columns:1fr}.mb-mode button{padding:20px}.mb-cast{gap:10px}.mb-character{padding:16px 6px}.mb-character strong{font-size:13px}.mb-poster{gap:8px}.mb-versus p{font-size:13px}.mb-reveal{gap:8px}.mb-reveal p{padding:11px}.mb-shell h1{letter-spacing:-1px}}
</style>
